// Tripwire logic ported from src/rules_engine.py (thresholds mirror config/rules.yaml).
const SEASONAL = {'01':100,'02':60,'03':60,'04':50,'05':50,'06':50,'07':40,'08':100,'09':100,'10':50,'11':50,'12':100};
const CAP_PCT = 1.30, BRAND_MAX_CPC = 2.0;
const today = new Date().toISOString().slice(0,10);
const month = today.slice(5,7);
const target = SEASONAL[month];
const snaps = ($input.all().flatMap(i => (i.json.snapshots || []))).filter(s => s.date === today);
const alerts = [];
const total = snaps.reduce((a,s)=>a+(s.spend_cad||0),0);
if (total > target*CAP_PCT) alerts.push(`ACCOUNT SPEND ${total.toFixed(2)} CAD exceeds ${CAP_PCT*100}% of seasonal target ${target}`);
for (const s of snaps) {
  if (s.is_brand && (s.cpc||0) > BRAND_MAX_CPC) alerts.push(`BRAND LEAKAGE: ${s.platform}/${s.campaign} CPC ${(s.cpc).toFixed(2)} > 2.00 - check negatives`);
  if (['MaximizeConversions','TargetCPA'].includes(s.bid_strategy)) alerts.push(`SMART BIDDING on ${s.platform}/${s.campaign} - verify >=15 verified registrations else flag`);
}
return [{ json: { date: today, alertCount: alerts.length, alerts } }];
